R=Path(__file__).resolve().parent
load=lambda n:json.loads((R/n).read_text())
def eth(v):return D(v)/D(10**18)
def fmt(v):return f'{D(v):,.6f}'
def main():
 fee=load('full_fee_distribution.json');inv=load('inventory_valued_ledger.json');lp=load('v3_position_accounting.json');lpv=load('v3_position_valuation.json');v2=load('target_v2_fee_accounting.json');cf=load('v2_local_counterfactuals.json');h=load('full_window_evidence.json');bal=load('fee_balance_validation.json');candidates=load('candidate_classification.json')['rows'];groups=load('sandwich_structure_groups.json')['groups']
 checks=[]
