 check('3311 continuous blocks no evidence errors',[r['block'] for r in h['rows']]==list(range(26300640,26303951)) and not h['errors'])
 check('751258 transaction receipts counted',sum(r['transactions'] for r in h['rows'])==751258 and sum(int(x['transactions']) for x in fee['categories'].values())==751258)
 check('burn plus priority equals gas every block',all(int(b['burn_wei'])+int(b['priority_wei'])==int(b['gas_wei']) for b in fee['blocks']))
 fields=list(fee['summary'])
 check('all fee totals equal block sum',all(sum(int(b[k]) for b in fee['blocks'])==int(fee['summary'][k]) for k in fields))
 check('fee recipient native conservation every block',all(int(b['priority_wei'])+int(b['direct_inflow_wei'])-int(b['direct_outflow_wei'])-int(b['fee_recipient_paid_gas_wei'])==int(b['fee_recipient_observed_execution_ETH_delta_wei']) for b in fee['blocks']))
 hs=[x for r in inv['rows'] for x in r['transaction_hashes']]
 check('disjoint strategy accounting transaction hashes',len(hs)==len(set(hs)))
