 check('missing inventory never filled zero',all((v['USD'] is None)==bool(v['missing_assets'] or v['ETH_cashflow_USD'] is None) for r in inv['rows'] for v in [r['strict'],r['five_minute']]))
 check('priced inventory cashflow arithmetic',all(D(v['USD'])==D(v['ETH_cashflow_USD'])+sum((D(a['USD']) for a in v['assets']),D(0)) for r in inv['rows'] for v in [r['strict'],r['five_minute']] if v['USD'] is not None))
 check('141 V3 positions reconcile',len(lp['rows'])==141 and all(p['status']=='reconciled' and p['liquidity_conservation'] for p in lp['rows']))
 check('V3 fee principal identity',all(int(p['collected_raw'][j])+int(p['states']['end'][f'owed{j}'])-int(p['states']['start'][f'owed{j}'])-int(p['principal_released_raw'][j])==int(p['fees_credited_in_window_raw'][j]) for p in lp['rows'] for j in [0,1]))
 check('proposer matched transfers equal recorded payout',all(sum(int(t['value_wei']) for t in p['transfers'])==int(p['value_wei']) for p in fee['proposer_payments']))
 check('proposer payouts unique by canonical block',len({p['block_hash'] for p in fee['proposer_payments']})==len(fee['proposer_payments']))
 check('30 independent historical balance comparisons pass',len(bal['rows'])==30 and all(r['match'] for r in bal['rows']))
 good=[x for x in cf['rows'] if x['status']=='verified_local_fixed_input']
 check('70 local counterfactual targets unique',len(good)==70 and len({x['target'] for x in good})==70)
 check('counterfactual reserve continuity',all(x['front_swap']['after']==x['target_swap']['before'] for x in good))
 check('counterfactual output delta arithmetic',all(int(x['without_front_output_raw'])-int(x['actual_target_output_raw'])==int(x['target_output_reduction_raw']) for x in good))
 check('527 V2 swaps match actual output formula',sum(r['status']=='verified_standard_swap' and r['output_formula_match'] for r in v2['rows'])==527)
 validation={'checks':checks,'passed':sum(x['passed'] for x in checks),'failed':sum(not x['passed'] for x in checks)};(R/'revenue_ledger_validation.json').write_text(json.dumps(validation,indent=2));assert not validation['failed'],validation
 recipients=defaultdict(lambda:defaultdict(int));proposers=defaultdict(lambda:defaultdict(int));traders=defaultdict(lambda:defaultdict(D))
 for b in fee['blocks']:
  d=recipients[b['fee_recipient']];d['blocks']+=1
  for k in fields:d[k]+=int(b[k])
  if 'proposer_execution_delta_wei' in b:
   q=proposers[b['proposer_fee_recipient']];q['blocks']+=1
   for k in ['proposer_native_inflow_wei','proposer_native_outflow_wei','proposer_paid_gas_wei','proposer_priority_wei','proposer_execution_delta_wei']:q[k]+=int(b[k])
 for p in fee['proposer_payments']:proposers[p['proposer_fee_recipient']]['matched_payment_wei']+=int(p['value_wei'])
 for r in inv['rows']:
  if r['kind']=='paired_strategy' and not r['position_or_debt_events'] and r['strict']['USD'] is not None:
   owner=';'.join(r['senders']);traders[owner]['groups']+=1;traders[owner]['marked_USD']+=D(r['strict']['USD'])
 recipient_out={'method':'Addresses, not identified persons. Block fee-recipient rows count activity only in blocks where address is fee recipient, not its whole-window personal profit. Proposer rows count only relay-covered blocks. Payments onward overlap fee-recipient outflows, do not sum them as new revenue. Trader rows use heuristic operational boundaries, not beneficial ownership.','block_fee_recipients':{a:{k:str(v) for k,v in d.items()} for a,d in recipients.items()},'proposer_recipients':{a:{k:str(v) for k,v in d.items()} for a,d in proposers.items()},'paired_strategy_senders':{a:{k:str(v) for k,v in d.items()} for a,d in traders.items()}}
 (R/'recipient_distribution_ledger.json').write_text(json.dumps(recipient_out,indent=2))
 with (R/'收款地址分配账.csv').open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.writer(f);w.writerow(['口径','地址','区块或组合数','优先费ETH','原生币流入ETH','原生币流出ETH','本地址GasETH','执行层ETH净变化','已匹配转付ETH','配对组合估值USD'])
  for a,d in recipients.items():w.writerow(['仅任区块费用收款地址的区块',a,d['blocks'],eth(d['priority_wei']),eth(d['direct_inflow_wei']),eth(d['direct_outflow_wei']),eth(d['fee_recipient_paid_gas_wei']),eth(d['fee_recipient_observed_execution_ETH_delta_wei']),'',''])
  for a,d in proposers.items():w.writerow(['仅有公开交付记录的提议者收款区块',a,d['blocks'],eth(d['proposer_priority_wei']),eth(d['proposer_native_inflow_wei']),eth(d['proposer_native_outflow_wei']),eth(d['proposer_paid_gas_wei']),eth(d['proposer_execution_delta_wei']),eth(d['matched_payment_wei']),''])
  for a,d in traders.items():w.writerow(['已完整估值配对策略交易发起者',a,d['groups'],'','','','','','',d['marked_USD']])
 with (R/'V3仓位本金手续费账.csv').open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.writer(f);w.writerow(['仓位编号','池','链上仓位owner','资产0','资产1','投入本金0原始单位','投入本金1原始单位','撤出本金0原始单位','撤出本金1原始单位','记账手续费0原始单位','记账手续费1原始单位','窗口内完整开平'])
  for p in lp['rows']:w.writerow([p['id'],p['pool'],p['owner'],p['token0'],p['token1'],*p['principal_added_raw'],*p['principal_released_raw'],*p['fees_credited_in_window_raw'],p['fully_opened_and_closed_in_window']])
 s=fee['summary'];strict=inv['summary']['paired_strategy:strict'];wide=inv['summary']['paired_strategy:five_minute'];lppriced=[x for x in lpv['rows'] if x.get('credited_fee_USD_at_last_event') is not None];lpclosed=[x for x in lpv['rows'] if x.get('closed_position_marked_cashflow_before_gas_USD') is not None];target=fee['categories']['target_pool_swap'];cand={k:sum(int(v.get(k,0)) for c,v in fee['categories'].items() if c.startswith('candidate:')) for k in ['gas_wei','burn_wei','priority_wei','direct_fee_recipient_inflow_wei']}
 lines=['# 收益与分配总账：新增核算结果','', '更新：2026-11-05。研究窗口：2026-10-29 19:58:23 至 10-30 07:02:47 UTC，Ethereum 区块 26300640–26303950。','', '**结论：原 12,934 笔候选的原生币收支缺口已归零；本轮进一步完成窗口费用分配账、V3 仓位本金分离、候选去重估值和 70 笔新增局部反事实。仍不能把这些不同口径相加成“黑客被 MEV 拿走的全事件精确金额”。**','', '## 老师要求与本轮实际完成','', '| 老师要回答的问题 | 本轮完成的工作 | 可以支持的结论 |','|---|---|---|', '| 损失是否来自交易排序和套利 | 70 笔官方 V2 池实际成交复现及移除前置交易的局部反事实；保留原双池案例 | 部分样本存在局部排序影响；未完成全市场行为反事实 |', '| 套利者到底赚多少 | 全部候选按配对策略去重；完整计入两腿现金流和可估值代币 | 已完整估值的配对样本有净资产变化；剩余不可估值项单列 |', '| LP 领取的钱是不是利润 | 141 个 V3 仓位全部本金与记账手续费对平；目标 V2 手续费核算 | 退回本金不能当作收入；仓位收益不等同事件 MEV |', '| 钱去了谁 | 区块费用收款地址、提议者收款地址、配对策略发起地址分别列账 | 地址级分配可查；不推定真实主体身份 |', '', '## 1. 配对套利策略的去重估值','',f'449 组前后手结构均保留。严格使用交易发生前已完成一分钟的价格，{strict["fully_priced_without_recognized_position_events"]} 组能完整估值且没有已识别仓位/债务事件，其中 {strict["positive"]} 组为正，合计标记净现金流 **${fmt(strict["marked_net_cashflow_USD"])}**。价格放宽到最多额外陈旧五分钟时，覆盖 {wide["fully_priced_without_recognized_position_events"]} 组，合计 **${fmt(wide["marked_net_cashflow_USD"])}**。两个数字样本不同，不是置信区间。','',f'配对组覆盖了候选集中的 {inv["paired_legs_in_candidate_set"]} 笔交易；这些交易已从单笔汇总移除。Gas 和直接原生币付款已经在现金流内扣除，不能再次扣除。另有 {len(inv["rows"])-449} 个未配对候选核算单元，不自动认定为完整策略。','', '操作地址边界包含调用到的路由器，不能证明这些地址属于同一受益人。残余借贷、窗口外头寸、跨交易所对冲也可能改变利润。因此这里给的是有明确假设的净资产变化，不是无条件套利利润。','', '价格按合约地址先查代币身份，再映射交易所产品。UNI、USDe、PEPE 的同名歧义另经项目官方资料处理；其他同名不明资产继续缺失。Binance 的 USDT 报价使用同期 USDT/USD 转换；WETH 按可兑换 ETH、WBTC 按 BTC 价格估值均为显式假设，不包含折价风险。无价格资产不记零。','', '## 2. LP 本金与手续费','',f'141 个候选相关 V3 仓位全部满足流动性守恒与代币对账，其中 {sum(p["fully_opened_and_closed_in_window"] for p in lp["rows"])} 个在窗口内完整开仓和平仓。三个曾无法读取起始状态的仓位已核实属于窗口内新建池，起始无合约代码的原始证据已保存。','', '每种资产均使用：**窗口内记账手续费 = 已领取金额 + 期末待领取金额 − 期初待领取金额 − Burn 撤出的本金。**','',f'{len(lppriced)} 个仓位的手续费资产可以估值，以各仓位最后事件时点价格标记，合计 **${fmt(sum((D(x["credited_fee_USD_at_last_event"]) for x in lppriced),D(0)))}**。{len(lpclosed)} 个完整开平且可估值仓位的领取减投入现金流为 **${fmt(sum((D(x["closed_position_marked_cashflow_before_gas_USD"]) for x in lpclosed),D(0)))}**，尚未扣除该策略全部 Gas、对冲等成本。后一个数包括资产价格和组成变化，不能称为手续费。','', '对于非完整开平仓位，窗口内记账的手续费可能在窗口前累积；期末尚未结晶的 fee growth 不在本式中。以上不代表所有 LP、不代表所有 V2/V4 仓位，也不证明全部由目标抛售造成。','',f'另对目标交易里的 556 次 V2 Swap 进行核验：527 次通过官方 factory/getPair 与 997 整数输出公式复现；其中 {v2["summary"]["priced_fee_swaps"]} 次手续费资产可估值，池内毛交易费合计 **${fmt(v2["summary"]["marked_gross_pool_fees_USD"])}**。这是 input×0.3% 的毛池费，留在储备中，未扣协议分成，也不是各 LP 净利润。','', '## 3. 区块费用与转付分配','', '| 窗口口径 | ETH | 含义 |','|---|---:|---|',f'| 全部交易 Gas | {fmt(eth(s["gas_wei"]))} | 所有交易，不只目标交易 |',f'| 基础费销毁 | {fmt(eth(s["burn_wei"]))} | 已销毁，不属于构建者/验证者收入 |',f'| 优先费 | {fmt(eth(s["priority_wei"]))} | 进入区块费用收款地址 |',f'| 费用收款地址原生币流入 | {fmt(eth(s["direct_inflow_wei"]))} | 与 Gas 分开，不自动全认定为小费 |',f'| 费用收款地址原生币流出 | {fmt(eth(s["direct_outflow_wei"]))} | 包含后续转付，不应再次当新收入 |',f'| 费用收款地址自身 Gas | {fmt(eth(s["fee_recipient_paid_gas_wei"]))} | 本地址发起交易的成本 |',f'| 对应区块执行层 ETH 净变化 | {fmt(eth(s["fee_recipient_observed_execution_ETH_delta_wei"]))} | 非构建者经济净利润；不含其他地址及结算 |','',f'1,102 笔目标池交易支付 Gas **{fmt(eth(target["gas_wei"]))} ETH**，其中销毁 {fmt(eth(target["burn_wei"]))}、优先费 {fmt(eth(target["priority_wei"]))} ETH；另有流向当块费用收款地址的原生币 **{fmt(eth(target.get("direct_fee_recipient_inflow_wei",0)))} ETH**。这给出目标交易可直接观测的费用去向，但不能把正常执行费用全部叫作 MEV。','',f'候选交易支付 Gas {fmt(eth(cand["gas_wei"]))} ETH、优先费 {fmt(eth(cand["priority_wei"]))} ETH，流向费用收款地址的原生币 {fmt(eth(cand["direct_fee_recipient_inflow_wei"]))} ETH。候选可能来自普通交易，不能全部归给黑客事件。','',f'四个公开 relay 的记录去重并与主链区块哈希核对，覆盖 {fee["relay_record_blocks"]} 块；其中 {fee["relay_matched_blocks"]} 块能把单笔或转付路径的付款逐笔匹配，合计 **{fmt(eth(fee["matched_proposer_payout_wei"]))} ETH**。另有多笔共同构成报价等情形，不强行塞进单笔付款样本。全部覆盖块均计算提议者地址的原生币流入、流出和自身 Gas；{sum(b.get("relay_value_matches_proposer_execution_delta",False) for b in fee["blocks"])} 块的执行层净变化与 relay 报价相等，其余差额保留。','', '付款合约使用 SELFDESTRUCT 转出 ETH 的路径已纳入。部分付款由费用付款钱包发起，不能仅看区块费用收款地址。提议者转付与前面的费用收款地址流出存在重叠，严禁把所有行相加。Relay 报价也可能与收款地址的其他交易活动不同，不能用报价代替完整余额账。','', '费用收款地址（按对应区块净变化排序，前五；不是全窗口个人净利润）：','', '| 地址 | 区块数 | 对应执行层净变化 ETH |','|---|---:|---:|']
 for a,d in sorted(recipients.items(),key=lambda x:x[1]['fee_recipient_observed_execution_ETH_delta_wei'],reverse=True)[:5]:lines.append(f'| `{a}` | {d["blocks"]} | {fmt(eth(d["fee_recipient_observed_execution_ETH_delta_wei"]))} |')
 lines+=['','提议者收款地址（按已匹配付款排序，前五）：','','| 地址 | 覆盖区块数 | 已匹配付款 ETH |','|---|---:|---:|']
 for a,d in sorted(proposers.items(),key=lambda x:x[1]['matched_payment_wei'],reverse=True)[:5]:lines.append(f'| `{a}` | {d["blocks"]} | {fmt(eth(d["matched_payment_wei"]))} |')
 lines+=['','## 4. 新增局部因果证据','',f'217 个 V2 夹击结构链接中，70 个不同目标交易满足严格局部模型条件：官方池身份核验、前手与目标的实际输出均按整数公式精确复现、前手后的储备等于目标前的储备、两者之间无其他改变池状态的事件。其余 147 个按原因排除，未强行拟合。','',f'保持目标卖出数量不变，仅撤掉紧邻前置交易，70 笔目标理论上能多收到的代币，按对应价格估值共 **${fmt(cf["summary"]["marked_target_output_reduction_USD"])}**。这个数是局部池输出减少的模型值，不是套利者最终拿到的钱；跨池输入、其他参与者行为、滑点保护和交易是否仍提交都固定。不能与前面的策略现金流、手续费或旧执行差额相加。','', '原有双池完整案例仍保留：后手单独增加 567.68 ETH，但合并前手后为 12.08 ETH；固定路径移除目标的局部模型差值为 23.83 ETH。两类实验移除的交易不同，不能混用。','', '## 5. 复核、文件及仍未完成的要求','',f'本轮 **{validation["passed"]} 项结构与金额检查全部通过**。另抽取 15 个区块，对费用收款地址和提议者地址进行 **30 次历史账户余额差额对比，全部吻合**。这些验证确认本轮实现的核算口径，不证明全事件覆盖或全部因果假设。','', '- `收益总账_去重估值.csv`：配对组与未配对候选；缺失价格保留空值。','- `收款地址分配账.csv`：费用收款地址、提议者地址、可估值配对策略发起者。','- `V3仓位本金手续费账.csv`：141 个仓位的本金和手续费原始单位。','- `inventory_valued_ledger.json`：逐资产价格、时间、缺失原因与假设。','- `full_fee_distribution.json`：逐块费用、relay 核验与原始付款路径。','- `v3_position_accounting.json`、`v3_position_valuation.json`：仓位等式与估值。','- `target_v2_fee_accounting.json`：556 次 V2 手续费核验结果。','- `v2_local_counterfactuals.json`：70 个通过样本与147个排除原因。','- `revenue_ledger_validation.json`、`fee_balance_validation.json`：复核结果。','', '**仍不能宣布老师全部任务完成。** 尚缺所选窗口外和其他链的同等覆盖、所有 V2/V4 与长期 LP/订单填充者/借贷的完整经济账、全部候选实际主体与跨交易成本、剩余代币可靠估值，以及全事件一致的反事实模型。这里的限制已具体落到记录和金额口径，不再笼统称为“内部转账数据没拿到”。本轮无需用户提供节点或密钥。','', '## 公开方法来源','', '- UNI 官方合约：https://developers.uniswap.org/docs/ecosystem/governance/uni','- USDe 官方合约：https://docs.ethena.fi/api-documentation/overview','- PEPE 官网与交易链接：https://www.pepe.vip/','- Ultra Sound relay 的调整付款及转付机制：https://github.com/ultrasoundmoney/relay-docs/blob/main/builders/bid-adjustment.md','- 实际金额依据本地保存的 dRPC 历史回执、调用轨迹、状态，以及 Coinbase/Binance 公开行情；以上网页只支持合约身份与机制，不替代逐笔金额证据。','']
 (R/'收益与分配总账报告.md').write_text('\n'.join(lines))
 banner='<!-- revenue-ledger-update -->\n> **2026-11-05 收益与分配核算更新：** 已补齐全窗口 3,311 块调用轨迹，141 个 V3 仓位本金/手续费全部对平，配对结构完成更新估值，新增70笔局部反事实与地址分配账。请优先阅读[收益与分配总账报告](收益与分配总账报告.md)。这些分项不可相加为全事件 MEV 总额。\n<!-- revenue-ledger-update-end -->\n\n'
